// ── PALMAS — Lago, Ponte FHC, Cerrado skyline ──
// mt, w1, w2, w3, w, h, bY, bCol, wc, ol, isN, sc — runtime

// Sky gradient (sunset dominant)
svg += `<defs><linearGradient id="lg-palmas" x1="0" y1="0" x2="0" y2="1">
  <stop offset="0%" stop-color="${isN ? '#1B263B' : sc.sky1}"/>
  <stop offset="100%" stop-color="${isN ? '#0D1B2A' : sc.sky2}"/>
</linearGradient></defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-palmas)"/>`;

// Lake (Lago de Palmas)
const lakeY = h * 0.62;
svg += `<rect x="0" y="${lakeY}" width="${w}" height="${h - lakeY}" fill="${isN ? '#0A1F2E' : '#3BA7C9'}"/>`;

// Water reflections
for (let i = 0; i < 6; i++) {
  const ry = lakeY + i * 7 + Math.sin(mt * 2 + i) * 2;
  svg += `<path d="M0 ${ry} Q ${w * 0.3} ${ry + 4 * w1} ${w * 0.6} ${ry} T ${w} ${ry}" fill="none" stroke="${isN ? '#6EC6FF' : '#ffffff'}" stroke-opacity="0.3" stroke-width="2"/>`;
}

// Ground strip (cerrado dry tone)
svg += `<rect x="0" y="${lakeY - 18}" width="${w}" height="18" fill="${sc.ground}"/>`;

// Cerrado vegetation (minimal shrubs)
for (let i = 0; i < 8; i++) {
  const gx = i * (w / 8);
  const gh = 8 + Math.sin(i * 1.3 + mt) * 2;
  svg += `<rect x="${gx + 10}" y="${lakeY - gh}" width="6" height="${gh}" fill="#7A8450" rx="2"/>`;
}

// Ponte FHC (bridge)
const bridgeY = lakeY - 25;
svg += `<rect x="${w * 0.1}" y="${bridgeY}" width="${w * 0.8}" height="4" fill="#444"/>`;

// Bridge cables (stylized)
for (let i = 0; i < 6; i++) {
  const bx = w * 0.15 + i * (w * 0.12);
  const byTop = bridgeY - 30 - w2 * 10;
  svg += `<line x1="${bx}" y1="${bridgeY}" x2="${bx}" y2="${byTop}" stroke="#888" stroke-width="1"/>`;
}

// Moving cars on bridge
for (let i = 0; i < 3; i++) {
  const carX = w * 0.1 + (w1 * w * 0.8 + i * 60) % (w * 0.8);
  svg += `<rect x="${carX}" y="${bridgeY - 3}" width="10" height="3" fill="${sc.acc}" rx="1"/>`;
}

// Skyline (planned city — spaced blocks)
for (let i = 0; i < 10; i++) {
  const sx = i * (w / 10);
  const sh = 20 + w2 * 25;
  svg += `<rect x="${sx + 5}" y="${bridgeY - sh}" width="${w / 18}" height="${sh}" fill="${sc.bld}" rx="2"/>`;

  if (isN) {
    const lp = Math.sin(mt * 2 + i) * 0.5 + 0.5;
    svg += `<rect x="${sx + 8}" y="${bridgeY - sh + 6}" width="3" height="3" fill="#FFD54F" opacity="${0.4 + lp * 0.6}"/>`;
  }
}

// Sun (strong Palmas identity)
if (!isN) {
  svg += `<circle cx="${w * 0.75}" cy="${h * 0.22}" r="${40 + w1 * 10}" fill="#FFD166" opacity="0.9"/>`;
  svg += `<circle cx="${w * 0.75}" cy="${h * 0.22}" r="${70 + w1 * 15}" fill="#FFD166" opacity="0.15"/>`;
} else {
  svg += `<circle cx="${w * 0.75}" cy="${h * 0.22}" r="20" fill="#EAE2CF"/>`;
}

// Heat shimmer effect (Palmas heat signature)
for (let i = 0; i < 5; i++) {
  const hx = w * 0.2 + i * 80;
  const hy = lakeY - 40;
  svg += `<path d="M${hx} ${hy} q5 -10 0 -20" stroke="rgba(255,255,255,0.15)" stroke-width="2" fill="none" opacity="${0.3 + w3 * 0.3}"/>`;
}
